package campaign

import (
	"encoding/json"
	"net/http"
	"strconv"

	"github.com/Berk-Cinek/Mini-Ad-Campaign/backend/internal/httpx"
)

type Handler struct {
	svc *Service
}

func NewHandler(svc *Service) *Handler {
	return &Handler{svc: svc}
}

func (h *Handler) Create(w http.ResponseWriter, r *http.Request) {
	var in CreateInput
	dec := json.NewDecoder(r.Body)
	dec.DisallowUnknownFields()
	if err := dec.Decode(&in); err != nil {
		httpx.WriteError(w, httpx.Invalid("invalid request body"))
		return
	}

	c, err := h.svc.Create(r.Context(), in)
	if err != nil {
		httpx.WriteError(w, err)
		return
	}
	httpx.WriteJSON(w, http.StatusCreated, c)
}

func (h *Handler) List(w http.ResponseWriter, r *http.Request) {
	campaigns, err := h.svc.List(r.Context())
	if err != nil {
		httpx.WriteError(w, err)
		return
	}
	httpx.WriteJSON(w, http.StatusOK, campaigns)
}

func (h *Handler) Get(w http.ResponseWriter, r *http.Request) {
	id, err := strconv.ParseInt(r.PathValue("id"), 10, 64)
	if err != nil {
		httpx.WriteError(w, httpx.Invalid("invalid campaign id"))
		return
	}

	c, err := h.svc.Get(r.Context(), id)
	if err != nil {
		httpx.WriteError(w, err)
		return
	}
	httpx.WriteJSON(w, http.StatusOK, c)
}

package campaign

import (
	"encoding/json"
	"time"
)

type Campaign struct {
	ID        int64     `json:"id"`
	Title     string    `json:"title"`
	Budget    int64     `json:"budget"`
	Spent     int64     `json:"spent"`
	Status    string    `json:"status"`
	StartDate time.Time `json:"start_date"`
	EndDate   time.Time `json:"end_date"`
	CreatedAt time.Time `json:"created_at"`
	UpdatedAt time.Time `json:"updated_at"`
}

// MarshalJSON adds a computed "remaining" field. Remaining budget is never
// stored (budget - spent), so it's derived here rather than on the struct.
func (c Campaign) MarshalJSON() ([]byte, error) {
	type Alias Campaign // defined type, not an alias — drops MarshalJSON so this doesn't recurse

	// pgx returns scanned timestamps in the driver/host's local Location; the
	// instant is correct but json's RFC3339 output would print that offset
	// instead of "Z". Normalize to UTC here so every response is UTC.
	c.StartDate = c.StartDate.UTC()
	c.EndDate = c.EndDate.UTC()
	c.CreatedAt = c.CreatedAt.UTC()
	c.UpdatedAt = c.UpdatedAt.UTC()

	return json.Marshal(struct {
		Alias
		Remaining int64 `json:"remaining"`
	}{
		Alias:     Alias(c),
		Remaining: c.Budget - c.Spent,
	})
}

type CreateInput struct {
	Title     string      `json:"title"`
	Budget    json.Number `json:"budget"`
	StartDate time.Time   `json:"start_date"`
	EndDate   time.Time   `json:"end_date"`
}

package campaign

import (
	"context"

	"github.com/jackc/pgx/v5/pgxpool"
)

type Repository struct {
	pool *pgxpool.Pool
}

func NewRepository(pool *pgxpool.Pool) *Repository {
	return &Repository{pool: pool}
}

const campaignColumns = "id, title, budget, spent, status, start_date, end_date, created_at, updated_at"

func (r *Repository) Create(ctx context.Context, c Campaign) (Campaign, error) {
	query := `
		INSERT INTO campaigns (title, budget, start_date, end_date)
		VALUES ($1, $2, $3, $4)
		RETURNING ` + campaignColumns

	var out Campaign
	err := r.pool.QueryRow(ctx, query, c.Title, c.Budget, c.StartDate, c.EndDate).Scan(
		&out.ID, &out.Title, &out.Budget, &out.Spent, &out.Status,
		&out.StartDate, &out.EndDate, &out.CreatedAt, &out.UpdatedAt,
	)
	if err != nil {
		return Campaign{}, err
	}
	return out, nil
}

func (r *Repository) List(ctx context.Context) ([]Campaign, error) {
	query := `
		SELECT ` + campaignColumns + `
		FROM campaigns
		WHERE deleted_at IS NULL
		ORDER BY created_at DESC`

	rows, err := r.pool.Query(ctx, query)
	if err != nil {
		return nil, err
	}
	defer rows.Close()

	campaigns := []Campaign{} // non-nil so a zero-row result marshals to [] not null
	for rows.Next() {
		var c Campaign
		if err := rows.Scan(
			&c.ID, &c.Title, &c.Budget, &c.Spent, &c.Status,
			&c.StartDate, &c.EndDate, &c.CreatedAt, &c.UpdatedAt,
		); err != nil {
			return nil, err
		}
		campaigns = append(campaigns, c)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return campaigns, nil
}

func (r *Repository) GetByID(ctx context.Context, id int64) (Campaign, error) {
	query := `
		SELECT ` + campaignColumns + `
		FROM campaigns
		WHERE id = $1 AND deleted_at IS NULL`

	var c Campaign
	err := r.pool.QueryRow(ctx, query, id).Scan(
		&c.ID, &c.Title, &c.Budget, &c.Spent, &c.Status,
		&c.StartDate, &c.EndDate, &c.CreatedAt, &c.UpdatedAt,
	)
	if err != nil {
		return Campaign{}, err
	}
	return c, nil
}

